# Issue #121 (S314): with no usable age the maximum is undefined. max() on an
# empty vector returned -Inf with a "no non-missing arguments to max" warning;
# the result is now NA_real_ with no warning, which is the sentinel
# getPyramidPlot() already guards with is.na().
test_that("getPedMaxAge ignores NA ages when some are present", {
  ped <- data.frame(id = LETTERS[1L:4L], age = c(NA, 2.5, 7.25, NA))
  expect_no_warning(res <- getPedMaxAge(ped))
  expect_equal(res, 7.25)
})

test_that("getPedMaxAge returns NA without warning when every age is NA", {
  ped <- data.frame(id = LETTERS[1L:3L], age = rep(NA_real_, 3L))
  expect_no_warning(res <- getPedMaxAge(ped))
  expect_true(is.na(res))
  expect_true(is.numeric(res))
})

test_that("getPedMaxAge returns NA without warning when there is no age column", {
  ped <- data.frame(id = LETTERS[1L:3L], stringsAsFactors = FALSE)
  expect_no_warning(res <- getPedMaxAge(ped))
  expect_true(is.na(res))
  expect_true(is.numeric(res))
})

test_that("getPedMaxAge returns NA without warning for a zero-row pedigree", {
  ped <- data.frame(id = character(0L), age = numeric(0L),
                    stringsAsFactors = FALSE)
  expect_no_warning(res <- getPedMaxAge(ped))
  expect_true(is.na(res))
  expect_true(is.numeric(res))
})

